uniform float3 A = float3(1.0, 0.0, 0.0);
uniform float3 B = float3(0.0, 0.0, 1.0);

export void M_DNamedArguments(inout material m)
{
    float T = UE.Time(Period = 2.0);
    float2 UV = UE.TextureCoordinate(CoordinateIndex = 1, UTiling = 2.0, VTiling = 3.0);

    m.EmissiveColor = UE.LinearInterpolate(A = A, B = B, Alpha = 0.25) * T;
    m.Opacity = UV.x;
}
